                    }
                    break;

                case '^':
                    if(mark->flags & MD_MARK_OPENER)
                        MD_ENTER_SPAN(MD_SPAN_SUPERSCRIPT, NULL);
                    else
                        MD_LEAVE_SPAN(MD_SPAN_SUPERSCRIPT, NULL);
                    break;

